-      }
-      const uint64_t config_flags = node->flags() &
-          (Node::PD::Flag_rvv_config_from_result | Node::PD::Flag_rvv_config_from_input);
-      if (config_flags == 0) {
-        if (previous_vl != 0 && !rvv_preserves_vsetvli(node, C->regalloc())) {
-          previous_vl = 0;
-        }
-        continue;
-      }
-      // Eligible nodes require m1/tu/mu and preserve the setup inserted here.
-      const Node* shape = rvv_config_shape_node(node->as_Mach());
-      assert(shape->bottom_type()->isa_vect() != nullptr, "simple RVV nodes require a vector shape");
-      BasicType bt = Matcher::vector_element_basic_type(shape);
-      Assembler::SEW sew = Assembler::elemtype_to_sew(bt);
-      uint vl = Matcher::vector_length(shape);
-      if (!can_eliminate || sew != previous_sew || vl != previous_vl) {
-        C->cfg()->insert(block, j, rvv_make_config_node(bt, vl));
-        // The operation moved one slot to the right and has already been analyzed.
-        j++;
-      }
-      node->add_flag(Node::PD::Flag_rvv_config_processed);
-      previous_sew = sew;
-      previous_vl = vl;
-    }
-    for (uint i = 0; i < block->_num_succs; i++) {
-      Block* succ = block->_succs[i];
-      if (succ == C->cfg()->get_root_block() || visited.test_set(succ->_pre_order)) {
-        continue;
-      }
-      // Input zero is reserved; every join starts a new EBB with unknown state.
-      uint vl = succ->num_preds() == 2 ? previous_vl : 0;
-      worklist.append({succ, previous_sew, vl});
-    }
-  }
